func (c *RuntimeCoordinator) harnessUnknown(ctx context.Context, project, runID string, epoch int64, reason string) error {
	if err := c.markUnknown(ctx, project, runID, epoch, reason); err != nil {
		return err
	}
	// Keep a trusted OBSERVED fact intact even if current authority prevents
	// reporting it. The public task remains UNKNOWN until real reconciliation.
	tx, err := c.service.DB.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	_, err = tx.Exec("UPDATE runtime_dispatches SET reason=?,updated_at=? WHERE project=? AND run=? AND epoch=?", reason, Now(), project, runID, epoch)
	if err != nil {
		tx.Rollback()
		return err
	}
	if err = tx.Commit(); err != nil {
		return err
	}
	return c.harnessTerminalEvent(ctx, project, runID)
}

