func (c *RuntimeCoordinator) harnessUnknown(ctx context.Context, project, runID string, epoch int64, reason string) error {
 // Harness UNKNOWN is one durable projection, not an acknowledged terminal
 // state followed by a best-effort event. Preserve the original queue fence
 // and historical OBSERVED proof; any event failure rolls this transaction
 // back while the already-claimed Run/dispatch still prevents a new launch.
 tx,err:=c.service.DB.BeginTx(ctx,nil);if err!=nil{return err}
 defer tx.Rollback()
 if err=resourceWriteLock(tx);err!=nil{return err}
 abandoned,err:=preparedRunAbandonmentExists(tx,project,runID,epoch);if err!=nil{return err};if abandoned{return nil}
 if err=unknownClientRunQueue(tx,project,runID,reason);err!=nil{return err}
 if _,err=tx.Exec("UPDATE runtime_dispatches SET state=CASE WHEN state='OBSERVED' THEN state ELSE 'UNKNOWN' END,reason=?,updated_at=? WHERE project=? AND run=? AND epoch=?",reason,Now(),project,runID,epoch);err!=nil{return err}
 run,err:=load(tx,project,"Run",runID);if err!=nil{return err}
 if Hash(run["lease_epoch"])==Hash(epoch)&&!runTerminal(run){
  if err=c.projectSessionRun(tx,project,run,nil,"Runtime outcome is unconfirmed: "+reason+"; wait for effect and process reconciliation.");err!=nil{return err}
 }
 task,err:=load(tx,project,"Task",Str(run,"task_id"));if err!=nil{return err}
 if err=c.harnessTerminalInTx(tx,project,task,run);err!=nil{return err}
 return tx.Commit()
}

