// The terminal persistence fault is installed only after the real owned fake
// process has stopped/drained, so earlier events remain a valid control.
type harnessAtomicFaultDriver struct{
 rt.CodexDriver
 db *sql.DB
 injected atomic.Bool
 starts atomic.Int64
}
type harnessAtomicFaultHandle struct{rt.CodexHandle;owner *harnessAtomicFaultDriver}
func(d *harnessAtomicFaultDriver)Start(ctx context.Context,in rt.CodexLaunch,cb rt.CodexCallbacks)(rt.CodexHandle,error){
 d.starts.Add(1)
 h,err:=d.CodexDriver.Start(ctx,in,cb);if err!=nil{return nil,err}
 return &harnessAtomicFaultHandle{CodexHandle:h,owner:d},nil
}
func(h *harnessAtomicFaultHandle)Wait(ctx context.Context)(rt.CodexResult,error){
 result,err:=h.CodexHandle.Wait(ctx);if err!=nil{return result,err}
 _,err=h.owner.db.Exec("CREATE TRIGGER harness_fixture_terminal_event_fault BEFORE INSERT ON domain_objects WHEN NEW.kind='EventEnvelope' BEGIN SELECT RAISE(ABORT,'author terminal persistence fixture fault'); END")
 if err==nil{h.owner.injected.Store(true)}
 return result,err
}
func TestHarnessUnknownTransitionAtomic(t *testing.T){
 f,c,b:=harnessFixture(t,harnessExecutable(t))
 driver:=&harnessAtomicFaultDriver{CodexDriver:c.config.HarnessDriver,db:f.db}
 c.config.HarnessDriver=driver
 id,_:=harnessSubmitFixture(t,f,c,b,"UNKNOWN")
 if err:=c.Scan(context.Background());err!=nil{t.Fatal(err)}
 c.workers.Wait()
 if !driver.injected.Load()||driver.starts.Load()!=1{t.Fatal("fault control did not follow exactly one owned process")}
 view:=harnessViewFixture(t,f,c,id)
 countTerminal:=func()(int,Object){
  page,err:=c.HarnessV1().Events(context.Background(),f.token,HarnessEvents{ProjectID:f.project,TaskID:id,Cursor:"0",Limit:500});if err!=nil{t.Fatal(err)}
  data:=page["data"].(map[string]any);n:=0
  for _,value:=range Arr(data,"events"){if value.(map[string]any)["kind"]=="TASK_TERMINAL"{n++}}
  return n,data
 }
 n,page:=countTerminal()
 if view["terminal"]!=false||n!=0||page["end"]!=false{t.Fatal("failed terminal event partially committed UNKNOWN",view,page)}
 runRef:=view["run"].(map[string]any);runID:=Str(runRef,"run_id");epoch,err:=HarnessDecimal(Str(runRef,"epoch"),true);if err!=nil{t.Fatal(err)}
 var state,reason string
 if err=f.db.QueryRow("SELECT state,reason FROM runtime_dispatches WHERE project=? AND run=? AND epoch=?",f.project,runID,epoch).Scan(&state,&reason);err!=nil{t.Fatal(err)}
 if state!="STARTED"||reason!=""{t.Fatal("unknown state/reason escaped failed transaction",state,reason)}
 if err=c.Scan(context.Background());err!=nil{t.Fatal(err)};c.workers.Wait()
 var runs int;if err=f.db.QueryRow("SELECT count(*) FROM domain_objects WHERE project=? AND kind='Run'",f.project).Scan(&runs);err!=nil{t.Fatal(err)}
 if runs!=1||driver.starts.Load()!=1{t.Fatal("terminal persistence failure re-dispatched the task")}
 // Explicit trusted reconciliation after fixing this fresh DB fault may
 // publish UNKNOWN; it grants no new execution or lease.
 if _,err=f.db.Exec("DROP TRIGGER harness_fixture_terminal_event_fault");err!=nil{t.Fatal(err)}
 if err=c.harnessUnknown(context.Background(),f.project,runID,epoch,"explicit fresh fixture reconciliation");err!=nil{t.Fatal(err)}
 view=harnessViewFixture(t,f,c,id);n,page=countTerminal()
 if view["status"]!="UNKNOWN"||view["terminal"]!=true||n!=1||page["end"]!=true{t.Fatal("UNKNOWN did not commit with its final event",view,page)}
 if err=c.harnessUnknown(context.Background(),f.project,runID,epoch,"same epoch repeated reconciliation");err!=nil{t.Fatal(err)}
 n,_=countTerminal();if n!=1||driver.starts.Load()!=1{t.Fatal("reconciliation duplicated terminal event or execution")}
}
